What is the output?
int Add(params int[] nums) {
  int sum = 0;
  foreach (int n in nums) sum += n;
  return sum;
}
Console.WriteLine(Add(1, 2, 3));

What is the output?
int Factorial(int n) {
  if (n <= 1) return 1;
  return n * Factorial(n - 1);
}
Console.WriteLine(Factorial(5));

